-- Safety Center Compliance Checklist -- add Chemical Splash Goggles to PPE.
--
-- Status: APPLIED to the live project (rewokyofschtvqgxrxwl) on 2026-09-30 via
-- psql (SUPABASE_DB_URL, ON_ERROR_STOP=1 --single-transaction). Verified after
-- apply: draft fields=56, the question and its notes field both present and
-- adjacent, published v2 still at 54 as expected.
--
-- The parts_directory row was inserted separately, guarded on the key not
-- already being mapped: 'Chemical Splash Goggles', Safety Supplies, vendor
-- 'Amazon - ProcureDesk', form_field_keys = {ppe_chemical_goggles}. 18 Safety
-- Supplies rows now, and 0 seeded keys that match no field on the draft.
--
-- STILL OUTSTANDING: Publish in the builder. Nothing reaches a site until then.
--
-- WHY IT IS NOT ON THE PAPER DOCUMENT: it was not, and it should have been.
-- Safety glasses are IMPACT protection and chemical goggles are SPLASH
-- protection. A site can hold a full box of the first and have nothing that
-- keeps an acid out of somebody's eyes, so one question covering both gets
-- answered "yes" on the strength of whichever is on the shelf. Separate
-- questions, separate orderable parts.
--
-- WHAT CHANGED vs form-02
--
--   +1 item    ppe_chemical_goggles ("Chemical Splash Goggles"), placed
--              immediately after ppe_safety_glasses, with its paired
--              ppe_chemical_goggles_notes (54 -> 56 fields, 21 -> 22 items).
--
--   Nothing else moves: no stage, workflow, lookup or certification change.
--
-- Generated by scripts/gen-safety-center.ts, which is the source of truth.
-- Do not hand-edit the JSON below; change the generator and re-run it.
-- Passed both validators at fields=56 items=22 paired=22 stages=5.
--
-- TARGETS THE DRAFT, resolved through forms.draft_version_id rather than a
-- literal id -- form-01 recorded one and it was stale within a day. v2 is the
-- live version at the time of writing and v3 is the draft this overwrites.
--
-- SAFE TO RE-RUN: it overwrites the draft's schema with a generated value
-- rather than inserting, so a second run against the same generator output is
-- a no-op.
--
-- DOES NOTHING UNTIL SOMEBODY PRESSES PUBLISH in the builder. Only submissions
-- made AFTER that carry the new question; earlier versions have no such field,
-- which is correct -- a checklist certified last week did not ask about
-- goggles and must not later appear to have.

update public.form_versions v
   set schema = '{"fields":[{"key":"site_number","type":"short_text","label":"Site number","helpText":"3-digit site number (leading zeros optional).","required":true,"maxLength":10,"id":"a9f66ff6"},{"key":"inspection_date","type":"date","label":"Inspection date","required":true,"defaultToToday":true,"id":"49131149"},{"key":"site_name","type":"lookup","label":"Site","required":false,"sourceTable":"pricing_simple","sourceColumn":"location_pretty","keyColumn":"pricing_simple.site","keyFieldId":"a9f66ff6","resolutionMode":"prefill_visible","nullBehavior":"allow_empty","id":"9ce5687b"},{"key":"rm_email","type":"lookup","label":"RM email","required":false,"sourceTable":"pricing_simple","sourceColumn":"rm_email","keyColumn":"pricing_simple.site","keyFieldId":"a9f66ff6","resolutionMode":"prefill_visible","nullBehavior":"allow_empty","id":"62289a42"},{"key":"site_email","type":"lookup","label":"Site email","required":false,"sourceTable":"pricing_simple","sourceColumn":"site_email","keyColumn":"pricing_simple.site","keyFieldId":"a9f66ff6","resolutionMode":"prefill_visible","nullBehavior":"allow_empty","id":"d0184168"},{"key":"manager","type":"short_text","label":"Manager","required":true,"maxLength":120,"id":"7cd78ae7"},{"key":"sec_ppe","type":"heading","label":"Personal Protective Equipment (PPE)","text":"Personal Protective Equipment (PPE)","level":"h3","required":false,"id":"c12b115b"},{"key":"ppe_safety_glasses","type":"radio","label":"Safety Glasses","layout":"inline","options":[{"label":"Yes","value":"yes"},{"label":"No","value":"no"}],"required":true,"action_item_eligible":true,"id":"5d2bcdc8"},{"key":"ppe_safety_glasses_notes","type":"short_text","label":"Safety Glasses (notes)","required":false,"maxLength":300,"id":"861a836a"},{"key":"ppe_chemical_goggles","type":"radio","label":"Chemical Splash Goggles","layout":"inline","options":[{"label":"Yes","value":"yes"},{"label":"No","value":"no"}],"required":true,"action_item_eligible":true,"id":"532745f4"},{"key":"ppe_chem