},{"key":"equip_spill_kit","type":"radio","label":"Spill Kit Fully Stocked","layout":"inline","options":[{"label":"Yes","value":"yes"},{"label":"No","value":"no"}],"required":true,"action_item_eligible":true,"id":"baa9b8d9"},{"key":"equip_spill_kit_notes","type":"short_text","label":"Spill Kit Fully Stocked (notes)","required":false,"maxLength":300,"id":"c030ee65"},{"key":"sec_prog","type":"heading","label":"Required Safety Programs","text":"Required Safety Programs","level":"h3","required":false,"id":"fffa48fa"},{"key":"prog_hazcom","type":"radio","label":"Hazard Communication (HazCom) Program","layout":"inline","options":[{"label":"Yes","value":"yes"},{"label":"No","value":"no"}],"required":true,"action_item_eligible":true,"id":"af081582"},{"key":"prog_hazcom_notes","type":"short_text","label":"Hazard Communication (HazCom) Program (notes)","required":false,"maxLength":300,"id":"70cd2f04"},{"key":"prog_spill_response","type":"radio","label":"Spill Response Program","layout":"inline","options":[{"label":"Yes","value":"yes"},{"label":"No","value":"no"}],"required":true,"action_item_eligible":true,"id":"caa4c54e"},{"key":"prog_spill_response_notes","type":"short_text","label":"Spill Response Program (notes)","required":false,"maxLength":300,"id":"67c71399"},{"key":"prog_sds","type":"radio","label":"SDS (Safety Data Sheet) Program","layout":"inline","options":[{"label":"Yes","value":"yes"},{"label":"No","value":"no"}],"required":true,"action_item_eligible":true,"id":"199f5366"},{"key":"prog_sds_notes","type":"short_text","label":"SDS (Safety Data Sheet) Program (notes)","required":false,"maxLength":300,"id":"eadaf855"},{"key":"prog_sds_binder","type":"radio","label":"Current SDS Binder Available","layout":"inline","options":[{"label":"Yes","value":"yes"},{"label":"No","value":"no"}],"required":true,"action_item_eligible":true,"id":"4606d364"},{"key":"prog_sds_binder_notes","type":"short_text","label":"Current SDS Binder Available (notes)","required":false,"maxLength":300,"id":"5a47fb15"},{"key":"sec_certification","type":"heading","label":"Manager Certification","text":"Manager Certification","level":"h3","required":false,"id":"8bd8f10f"},{"key":"manager_signature","type":"signature","label":"Manager signature","helpText":"I certify that I have inspected the Safety Center and verified the status of all required safety supplies, equipment, and programs listed above.","required":true,"format":"png","id":"f9c4e381"}],"workflow":{"default_stage":"notify_site","stages":[{"id":"notify_site","label":"Copy to the site","kind":"email","recipients":[{"type":"payload_field","field_key":"site_email"}],"subject_template":"Safety Center checklist completed - {field.site_name} (site {field.site_number})","body_template":"{field.manager} completed the Safety Center Compliance Checklist for {field.site_name} (site {field.site_number}) on {field.inspection_date}.\n\nYour full copy is attached. Every answer is below.\n\n{payload.summary}\n\n{parts.needed}\n\nAnything answered No is also on your action items page, where it stays until it is closed out.","attach_pdf":true,"transitions":[{"to":"notify_rm","label":"Email the RM"}]},{"id":"notify_rm","label":"Email the RM","kind":"email","recipients":[{"type":"payload_field","field_key":"rm_email"}],"subject_template":"Safety Center checklist for review - {field.site_name} (site {field.site_number})","body_template":"{field.manager} completed the Safety Center Compliance Checklist for {field.site_name} (site {field.site_number}) on {field.inspection_date}.\n\nThe completed checklist is attached, including any corrective action items raised. Those items are also on the site''s action items page.\n\nReview here:\n\n{submission.url}","attach_pdf":true,"transitions":[{"to":"rm_review","label":"Move to RM review"}]},{"id":"rm_review","label":"RM review","kind":"approval","approver_source":{"type":"payload_field","field_key":"rm_email"},"transitions":[{"to":"reviewed","label":"Mark reviewed","requires":{"typed_name":true}},{"to":"returned","label":"Send back","requires":{"note":true}}]},{"id":"reviewed","label":"Reviewed","kind":"outcome","tint":"success","transitions":[]},{"id":"returned","label":"Sent back","kind":"outcome","tint":"warning","transitions":[]}]}}'::jsonb
  from public.forms f
 where f.slug = 'safety-center'
   and v.id = f.draft_version_id;

-- Proof rather than assumption: the draft must now carry the question AND its
-- notes field, and the pairing is what the PDF's checklist layout keys off.
select jsonb_array_length(v.schema->'fields')                            as fields,
       (v.schema->'fields') @> '[{"key":"ppe_chemical_goggles"}]'::jsonb as has_item,
       (v.schema->'fields') @> '[{"key":"ppe_chemical_goggles_notes"}]'::jsonb as has_notes
  from public.forms f
  join public.form_versions v on v.id = f.draft_version_id
 where f.slug = 'safety-center';
